<?php require '../includes/bootstrap.php';require '../includes/operations.php';$user=staff_required();$title='Sơ đồ phòng';$error='';
if(post()){check_csrf();try{db()->beginTransaction();update_room_state((int)input('id'),input('housekeeping'));db()->commit();flash('Đã cập nhật tình trạng phòng.');go('reception/rooms.php');}catch(DomainException $ex){if(db()->inTransaction())db()->rollBack();$error=$ex->getMessage();}}
$rooms=query("SELECT h.*,r.name room_name,(SELECT b.id FROM room_assignments a JOIN bookings b ON b.id=a.booking_id WHERE a.room_id=h.id AND b.status='checked_in' LIMIT 1) stay_id FROM hotel_rooms h JOIN room_types r ON r.id=h.room_type_id ORDER BY h.room_type_id,h.number")->fetchAll();
$legacy=query("SELECT b.id,b.guest_name FROM bookings b WHERE b.status='checked_in' AND (SELECT COUNT(*) FROM room_assignments a WHERE a.booking_id=b.id)<>b.quantity")->fetchAll();
$overdue=query("SELECT id,guest_name FROM bookings WHERE status='checked_in' AND check_out<CURDATE()")->fetchAll();
require '../includes/staff_header.php'; ?><p>Trạng thái khách đang ở được lấy từ đơn nhận phòng. Phòng chờ dọn vẫn tính vào tồn đặt trước; chỉ phòng đã dọn được giao cho khách. Bảo trì/ngừng sử dụng làm giảm tồn nhận đặt.</p>
<?php if($legacy): ?><div class="notice error">Đơn đang lưu trú từ bản cũ cần bổ sung số phòng thực tế: <?php foreach($legacy as $b): ?><a href="<?=e(url('reception/booking.php?id='.$b['id']))?>">#<?=$b['id']?> <?=e($b['guest_name'])?></a> · <?php endforeach; ?></div><?php endif; if($overdue): ?><div class="notice error">Khách quá ngày trả phòng, cần xử lý: <?php foreach($overdue as $b): ?><a href="<?=e(url('reception/booking.php?id='.$b['id']))?>">#<?=$b['id']?> <?=e($b['guest_name'])?></a> · <?php endforeach; ?> Các đơn này tiếp tục chặn tồn đặt mới cho đến khi trả phòng.</div><?php endif; ?>
<div class="physical-grid"><?php foreach($rooms as $r): $state=$r['stay_id']?'occupied':(!$r['active']?'inactive':$r['housekeeping']);$labels=['occupied'=>'Đang có khách','inactive'=>'Ngừng sử dụng','ready'=>'Sẵn sàng','dirty'=>'Chờ dọn','maintenance'=>'Bảo trì']; ?><article class="physical-card state-<?=e($state)?>"><span class="badge"><?=e($labels[$state])?></span><h2><?=e($r['number'])?></h2><p><?=e($r['room_name'])?></p><?php if($r['stay_id']): ?><a class="text-link" href="<?=e(url('reception/booking.php?id='.$r['stay_id']))?>">Xử lý đơn #<?=$r['stay_id']?> ↗</a><?php elseif($r['active']): ?><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=$r['id']?>"><label>Tình trạng<select name="housekeeping"><?php foreach(['ready'=>'Sẵn sàng','dirty'=>'Chờ dọn','maintenance'=>'Bảo trì'] as $k=>$label): ?><option value="<?=$k?>" <?=$r['housekeeping']===$k?'selected':''?>><?=e($label)?></option><?php endforeach; ?></select></label><button class="small-button">CẬP NHẬT</button></form><?php endif; ?></article><?php endforeach; ?></div><?php require '../includes/staff_footer.php'; ?>
